    afterModelResponse: async (_session, _responseText, usage) => {
      received = usage;
    },
  };

  const orchestrator = createChatOrchestrator(scriptedRounds(rounds), new PromptBuilder({identity: 'You are a test assistant.'}), registryReturning({result: 'r'}), {hooks});
  await orchestrator.processMessage(createSession('ask'));

  return received;
}

